// dbt incremental: config(materialized='incremental', incremental_strategy='merge', unique_key='event_id')
function loadBatch(table, batch) {
  for (const row of batch) {
    const i = table.findIndex(function (r) { return r.event_id === row.event_id; });
    if (i >= 0) { table[i] = row; }   // key exists -> update (upsert)
    else { table.push(row); }          // new key -> insert
  }
  return table;
}

const batch = [
  { event_id: 'e1', amount: 100 },
  { event_id: 'e2', amount: 250 },
  { event_id: 'e3', amount: 75 },
];

const table = [];
loadBatch(table, batch);   // first run
loadBatch(table, batch);   // retry of the SAME batch (transient-failure replay)

const total = table.reduce(function (s, r) { return s + r.amount; }, 0);
console.log('rows=' + table.length + ' total=' + total);
